CREATE TABLE public.video_caption_cues (video_id text PRIMARY KEY REFERENCES public.videos(id), cues jsonb NOT NULL, extracted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_caption_cues TO authenticated; GRANT ALL ON public.video_caption_cues TO service_role;
ALTER TABLE public.video_caption_cues ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_caption_unlocks (user_id uuid NOT NULL, video_id text NOT NULL REFERENCES public.videos(id), unlocked_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,video_id));
GRANT SELECT ON public.user_caption_unlocks TO authenticated; GRANT ALL ON public.user_caption_unlocks TO service_role;
ALTER TABLE public.user_caption_unlocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_caption_unlocks ON public.user_caption_unlocks FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY unlocked_caption_cues ON public.video_caption_cues FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_caption_unlocks u WHERE u.user_id=auth.uid() AND u.video_id=video_caption_cues.video_id));
CREATE TABLE public.collection_videos (collection_id text NOT NULL REFERENCES public.channels(id), video_id text NOT NULL REFERENCES public.videos(id), position integer NOT NULL DEFAULT 0, PRIMARY KEY(collection_id,video_id));
GRANT SELECT ON public.collection_videos TO anon, authenticated; GRANT ALL ON public.collection_videos TO service_role;
ALTER TABLE public.collection_videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_collection_metadata ON public.collection_videos FOR SELECT TO anon, authenticated USING(true);
CREATE OR REPLACE FUNCTION public.user_channel_remaining(_user uuid, _channel text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::int FROM videos v WHERE (v.channel_id=_channel OR EXISTS(SELECT 1 FROM collection_videos c WHERE c.collection_id=_channel AND c.video_id=v.id)) AND (v.status='pending' OR (v.status='ok' AND NOT EXISTS(SELECT 1 FROM user_video_unlocks u WHERE u.user_id=_user AND u.video_id=v.id))) $$;
CREATE OR REPLACE FUNCTION public.user_channel_todo(_user uuid,_channel text,_limit integer) RETURNS TABLE(id text,status text,attempts integer,title text,views bigint,duration_seconds integer,publish_date timestamptz,cached boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.id,v.status,v.attempts,v.title,v.views,v.duration_seconds,v.publish_date,EXISTS(SELECT 1 FROM video_transcripts t WHERE t.video_id=v.id) FROM videos v LEFT JOIN collection_videos c ON c.video_id=v.id AND c.collection_id=_channel WHERE (v.channel_id=_channel OR c.video_id IS NOT NULL) AND (v.status='pending' OR (v.status='ok' AND NOT EXISTS(SELECT 1 FROM user_video_unlocks u WHERE u.user_id=_user AND u.video_id=v.id))) ORDER BY coalesce(c.position,v.position) LIMIT least(_limit,9) $$;
REVOKE ALL ON FUNCTION public.user_channel_remaining(uuid,text), public.user_channel_todo(uuid,text,integer) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.user_channel_remaining(uuid,text), public.user_channel_todo(uuid,text,integer) TO service_role;
CREATE FUNCTION public.deliver_caption_unlock(_user uuid,_video text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE used_count integer; balance integer; free_count integer:=0; paid_count integer:=0; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,0));
IF NOT EXISTS(SELECT 1 FROM user_video_unlocks WHERE user_id=_user AND video_id=_video) THEN RETURN jsonb_build_object('delivered',false,'reason','transcript_locked'); END IF;
IF EXISTS(SELECT 1 FROM user_caption_unlocks WHERE user_id=_user AND video_id=_video) THEN RETURN jsonb_build_object('delivered',true,'reason','already_unlocked'); END IF;
IF NOT EXISTS(SELECT 1 FROM video_caption_cues WHERE video_id=_video) THEN RETURN jsonb_build_object('delivered',false,'reason','no_timestamps'); END IF;
INSERT INTO wallets(user_id,credits) VALUES(_user,0) ON CONFLICT DO NOTHING;
INSERT INTO daily_usage(user_id,day,used) VALUES(_user,(now() AT TIME ZONE 'UTC')::date,0) ON CONFLICT DO NOTHING;
SELECT coalesce(used,0) INTO used_count FROM daily_usage WHERE user_id=_user AND day=(now() AT TIME ZONE 'UTC')::date FOR UPDATE;
SELECT coalesce(credits,0) INTO balance FROM wallets WHERE user_id=_user FOR UPDATE;
IF used_count<10 THEN free_count:=1; ELSIF balance>0 THEN paid_count:=1; ELSE RETURN jsonb_build_object('delivered',false,'reason','quota'); END IF;
INSERT INTO user_caption_unlocks(user_id,video_id) VALUES(_user,_video);
UPDATE daily_usage SET used=used_count+free_count WHERE user_id=_user AND day=(now() AT TIME ZONE 'UTC')::date;
UPDATE wallets SET credits=balance-paid_count,updated_at=now() WHERE user_id=_user;
INSERT INTO credit_ledger(user_id,delta,free_used,type,description) VALUES(_user,-paid_count,free_count,'timestamp_refresh','Timestamp refresh: '||_video);
RETURN jsonb_build_object('delivered',true,'reason','unlocked'); END $$;
REVOKE ALL ON FUNCTION public.deliver_caption_unlock(uuid,text) FROM public,anon,authenticated; GRANT EXECUTE ON FUNCTION public.deliver_caption_unlock(uuid,text) TO service_role;